function initScene(){scene=new THREE.Scene();scene.background=new THREE.Color('#e7ece3');world=new THREE.Group();scene.add(world);scene.fog=new THREE.Fog('#e7ece3',85,170);camera=new THREE.PerspectiveCamera(36,1,.02,180);renderer=new THREE.WebGLRenderer({antialias:true,alpha:false,preserveDrawingBuffer:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=.9;$('scene').append(renderer.domElement);controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=true;controls.maxPolarAngle=Math.PI*.485;controls.minDistance=1;controls.maxDistance=65;scene.add(new THREE.HemisphereLight(0xf9fff2,0x6f8978,1.5));const sun=new THREE.DirectionalLight(0xfff5d4,2.1);sun.position.set(-12,23,-8);scene.add(sun);const fill=new THREE.DirectionalLight(0xa2dce1,.7);fill.position.set(10,4,8);scene.add(fill);riverGroup=new THREE.Group();boundaryGroup=new THREE.Group();waterGroup=new THREE.Group();baseGroup=new THREE.Group();world.add(riverGroup,boundaryGroup,waterGroup,baseGroup);const observer=new ResizeObserver(resize);for(const id of ['viewport','hydroPane','erosionPane'])observer.observe($(id));resize()}
