    const rings=w.geometry.coordinates;
    const shape=new THREE.Shape(rings[0].map(p=>{const [x,z]=xy(...p);return new THREE.Vector2(x,-z)}));
    shape.holes=rings.slice(1).map(r=>new THREE.Path(r.map(p=>{const [x,z]=xy(...p);return new THREE.Vector2(x,-z)})));
