function densify(seg){const out=[];for(let i=1;i<seg.length;i++){const a=seg[i-1],b=seg[i],dist=Math.hypot((b[0]-a[0])*62000,(b[1]-a[1])*111320),n=Math.max(1,Math.ceil(dist/25));for(let j=0;j<n;j++)out.push([a[0]+(b[0]-a[0])*j/n,a[1]+(b[1]-a[1])*j/n])}out.push(seg[seg.length-1]);return out}
function deformed(seg,riverIndex=state.selected){if(state.mode!=='erosion'||!state.lab||state.compare||state.year===0)return seg;const moved=seg.map((p,i)=>{if(i<2||i>seg.length-3)return p;const a=seg[Math.max(0,i-8)],b=seg[Math.min(seg.length-1,i+8)];const dx=(b[0]-a[0])*62000,dz=(b[1]-a[1])*111320,len=Math.hypot(dx,dz)||1;const nx=-dz/len,nz=dx/len;const mid=[(a[0]+b[0])/2,(a[1]+b[1])/2];const curve=((p[0]-mid[0])*62000*nx+(p[1]-mid[1])*111320*nz);const shift=Math.tanh(curve/15)*state.year*.7*state.flow*(.35+state.sed)*Math.sin(i/(seg.length-1)*Math.PI);const next=[p[0]+nx*shift/62000,p[1]+nz*shift/111320];const allowed=rivers[riverIndex]?.name==='Волга'?next[0]>=meta.bounds[0]&&next[0]<=meta.bounds[2]&&next[1]>=meta.bounds[1]&&next[1]<=meta.bounds[3]:inCity(next);return allowed?next:p});return seg.map((p,i)=>{if(i<2||i>seg.length-3)return p;let x=0,y=0,n=0;for(let j=Math.max(0,i-6);j<=Math.min(seg.length-1,i+6);j++){const weight=7-Math.abs(i-j);x+=(moved[j][0]-seg[j][0])*weight;y+=(moved[j][1]-seg[j][1])*weight;n+=weight}const q=[p[0]+x/n,p[1]+y/n];return rivers[riverIndex]?.name==='Волга'||inCity(q)?q:p})}
