  buildRivers();const stats=evolution.stats();$('changeStats').textContent=state.compare?'Исходный рельеф':state.year>0?`Размыв −${stats.cut.toFixed(1)} м · наносы +${stats.fill.toFixed(1)} м`:'Год 0 · исходный рельеф';$('changeStats').dataset.cells=stats.cells;$('changeStats').dataset.cut=stats.cut;$('changeStats').dataset.fill=stats.fill;
