function setYear(value){state.year=THREE.MathUtils.clamp(value,0,200);state.lab=true;syncLab();applyEvolution();lastLab=Math.floor(state.year)}
function focusBend(){if(state.selected<0)select(rivers.findIndex(r=>r.name==='Сугутка'));let best=null,score=-1;for(const raw of rivers[state.selected].segments){const seg=densify(raw);for(let i=8;i<seg.length-8;i++){const a=xy(...seg[i-8]),p=xy(...seg[i]),b=xy(...seg[i+8]);const bend=Math.hypot(p[0]-(a[0]+b[0])/2,p[1]-(a[1]+b[1])/2);if(bend>score){score=bend;best=seg[i]}}}if(!best){frame();return}const center=point(...best);center.y*=state.exag/12;controls.target.copy(center);const dist=rivers[state.selected].name==='Волга'?5:3.2;camera.position.copy(center).add(state.top?v3(0,dist,.001):v3(dist*.32,dist*.8,dist*.85));controls.update()}
function setExag(value){state.exag=value;$('exag').value=value;$('exagValue').textContent=value+'×';world.scale.y=value/12;}
function togglePlay(){if(state.mode==='hydrology'){hydrology.toggleSeason();return;}if(state.year>=200&&!state.evolving)setYear(0);state.evolving=!state.evolving;syncLab()}
function wire(){ $('waterFocus').onclick=()=>{const sections=hydroData.sections;hydrology.onWaveFocus(sections[Math.floor(sections.length/2)].center,500);};for(const b of document.querySelectorAll('[data-mode]'))b.onclick=()=>{if($('info').open)$('info').close();setMode(b.dataset.mode);};rivers.forEach((r,i)=>{const b=document.createElement('button');b.className='river';b.dataset.river=i;const label=document.createElement('span');label.textContent=r.name;const length=document.createElement('small');length.textContent=fmt(r.length)+' км';b.append(label,length);b.onclick=()=>select(i);$('rivers').append(b)});$('all').dataset.river=-1;$('all').onclick=()=>select(-1);$('exag').oninput=e=>setExag(Number(e.target.value));$('flow').oninput=e=>{state.flow=Number(e.target.value);$('flowValue').textContent=state.flow.toFixed(1)+'×';applyEvolution()};$('sed').oninput=e=>{state.sed=Number(e.target.value);$('sedValue').textContent=state.sed.toFixed(1);applyEvolution()};$('year').oninput=e=>{state.evolving=false;setYear(Number(e.target.value))};$('play').onclick=togglePlay;$('experiment').onclick=()=>{state.evolving=false;state.compare=false;setYear(0)};$('compare').onclick=()=>{state.compare=!state.compare;syncLab();applyEvolution()};$('bend').onclick=focusBend;$('record').onclick=recordVideo;$('view3d').onclick=()=>setView(false);$('viewTop').onclick=()=>setView(true);$('reset').onclick=frame;for(const id of ['about','sources'])$(id).onclick=()=>$('info').showModal();$('closeInfo').onclick=()=>$('info').close();$('info').onclick=e=>{if(e.target===$('info')){const r=$('info').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('info').close()}};window.addEventListener('keydown',e=>{if(e.code==='Space'&&!['INPUT','BUTTON','TEXTAREA','SELECT'].includes(e.target.tagName)&&!$('info').open){e.preventDefault();togglePlay()}});let down;renderer.domElement.addEventListener('pointerdown',e=>down=[e.clientX,e.clientY]);renderer.domElement.addEventListener('pointerup',e=>{if(!down||Math.hypot(e.clientX-down[0],e.clientY-down[1])>5||e.button!==0)return;const r=renderer.domElement.getBoundingClientRect(),ray=new THREE.Raycaster();ray.setFromCamera(new THREE.Vector2((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1),camera);const hit=ray.intersectObjects(riverGroup.children).find(h=>h.object.userData.river!==undefined);if(hydrology?.pick(ray))return;if(hit)select(hit.object.userData.river)});$('heightLegend').textContent=`${Math.round(meta.min)}–${Math.round(meta.max)}`}
// North is -z; with the camera east of target its screen projection points right.
function compassRotation(x,z){return Math.atan2(x,z)}
function setView(top){state.top=top;$('view3d').classList.toggle('active',!top);$('viewTop').classList.toggle('active',top);frame()}
async function recordVideo(){
  if(recording)return;
  if(!window.MediaRecorder||!HTMLCanvasElement.prototype.captureStream){alert('Этот браузер не поддерживает запись видео. Откройте карту в Chrome или Edge.');return}
  if(state.selected<0)select(rivers.findIndex(r=>r.name==='Сугутка'));
  state.evolving=false;state.compare=false;setExag(5);setYear(0);focusBend();camera.clearViewOffset();camera.aspect=1280/720;camera.updateProjectionMatrix();renderer.setSize(1280,720,false);controls.enabled=false;
  const canvas=document.createElement('canvas');canvas.width=1280;canvas.height=720;
  const ctx=canvas.getContext('2d');const stream=canvas.captureStream(24);
  const mime=['video/webm;codecs=vp9','video/webm;codecs=vp8','video/mp4'].find(t=>MediaRecorder.isTypeSupported(t));
  if(!mime){stream.getTracks().forEach(t=>t.stop());alert('Нет доступного формата записи.');return}
  const recorder=new MediaRecorder(stream,{mimeType:mime,videoBitsPerSecond:6000000}),chunks=[];
  const extension=mime.includes('mp4')?'mp4':'webm';
  const session={canvas,ctx,recorder,stream,chunks,start:performance.now(),last:-1,duration:26000};
  recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};
  recorder.onstop=()=>{stream.getTracks().forEach(t=>t.stop());const blob=new Blob(chunks,{type:mime});let a=$('videoDownload');if(a){URL.revokeObjectURL(a.href)}else{a=document.createElement('a');a.id='videoDownload';$('record').after(a)}a.href=URL.createObjectURL(blob);a.download='cheboksary-river-evolution.'+extension;a.textContent='Скачать видео';if(location.hostname==='127.0.0.1'&&new URLSearchParams(location.search).has('saveVideo'))fetch('/__recording',{method:'POST',headers:{'Content-Type':mime},body:blob}).then(r=>{if(!r.ok)throw Error('Не удалось сохранить запись');a.textContent='Видео сохранено'}).catch(console.error);$('record').textContent='Видео ↓';$('record').disabled=false;recording=null;controls.enabled=true;resize();syncLab()};
  recorder.onerror=()=>{$('record').disabled=false;$('record').textContent='Повторить видео';stream.getTracks().forEach(t=>t.stop());recording=null;controls.enabled=true;resize()};
  recording=session;$('record').disabled=true;recorder.start(1000);
}
function captureFrame(now){if(!recording)return;const r=recording,elapsed=Math.max(0,now-r.start);const progress=THREE.MathUtils.clamp((elapsed-2500)/20000,0,1),year=Math.round(progress*200);
  if(year!==r.last){r.last=year;setYear(year);renderer.render(scene,camera)}
  const ctx=r.ctx;ctx.fillStyle='#e7ece3';ctx.fillRect(0,0,1280,720);const source=renderer.domElement;const fit=Math.min(1280/source.width,720/source.height),w=source.width*fit,h=source.height*fit;ctx.drawImage(source,(1280-w)/2,(720-h)/2,w,h);
  ctx.fillStyle='rgba(246,248,238,.94)';ctx.fillRect(28,26,620,96);ctx.fillStyle='#254d43';ctx.font='bold 28px Arial';ctx.fillText(rivers[state.selected]?.name||'Реки Чебоксар',48,65);ctx.font='20px Arial';ctx.fillText('Год '+year+' · '+$('changeStats').textContent,48,101);
  ctx.fillStyle='rgba(246,248,238,.94)';ctx.fillRect(28,658,930,38);ctx.font='16px Arial';ctx.fillStyle='#435b4f';ctx.fillText('Условная модель · терракота: размыв · песочный: наносы · Copernicus GLO-30 / OpenStreetMap',42,683);
  $('record').textContent='Запись '+Math.round(Math.min(1,elapsed/r.duration)*100)+'%';
  if(elapsed>=r.duration&&r.recorder.state==='recording')r.recorder.stop();
}
function webMCP(){const context=document.modelContext;if(!context?.registerTool)return;const life=new AbortController();window.addEventListener('pagehide',()=>life.abort(),{once:true});for(const tool of [{name:'list_city_rivers',description:'List the OSM rivers in Cheboksary and the adjacent Volga frontage, with displayed lengths.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:input=>{if(!input||Object.keys(input).length)throw Error('Expected an empty object');return rivers.map(r=>({name:r.name,lengthMeters:r.length}))}},{name:'select_city_river',description:'Select a river on the visible 3D map. Use an exact name from list_city_rivers, or Весь город.',inputSchema:{type:'object',properties:{name:{type:'string'}},required:['name'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||typeof input.name!=='string')throw Error('name is required');const i=input.name==='Весь город'?-1:rivers.findIndex(r=>r.name===input.name);if(i<0&&input.name!=='Весь город')throw Error('Unknown river');select(i);return {selected:$('title').textContent}}}]){try{Promise.resolve(context.registerTool(tool,{signal:life.signal})).catch(()=>{})}catch{}}}
function setMode(mode){
  if(recording)return;

  state.mode=mode;state.year=0;state.evolving=false;state.compare=false;
  if(mode==='erosion')hydrology.setRunning(false);hydrology.group.visible=mode==='hydrology';
  $('hydroPane').hidden=mode!=='hydrology';$('erosionPane').hidden=mode!=='erosion';
  $('hydroSidebar').hidden=mode!=='hydrology';
  $('modelBadge').textContent=mode==='hydrology'?'Сценарная модель · OSM + DSM':'Эскиз размыва · не физический прогноз';
  syncLab();applyEvolution();setHydraulicBed(hydrology.flowField);resize();
  if(mode==='erosion'){for(const mesh of waterGroup.children){mesh.position.y=0;mesh.visible=true;}}else{hydrology.update();if(hydrology.flowField)hydrology.onLevel(null);}
}
async function start(){try{
  const names=['terrain.json','terrain.bin','rivers.json','boundary.json','water.json','surface-mask.bin','buildings.json','building-mask.bin','volga-mask.bin','hydrology.json'];
  const responses=await Promise.all(names.map(p=>fetch('data/'+p).then(r=>{if(!r.ok)throw Error('Не удалось загрузить '+p);return p.endsWith('.bin')?r.arrayBuffer():r.json()})));
  [meta,,rivers,boundary,waters]=responses;heights=new Float32Array(responses[1]);surfaceMask=new Uint8Array(responses[5]);volgaMask=new Uint8Array(responses[8]);hydroData=responses[9];
  evolution=new TerrainEvolution(meta,heights);if(heights.length!==meta.width*meta.height)throw Error('Неполная сетка высот');
  const [w,s,e,n]=meta.bounds;lon0=(w+e)/2;lat0=(s+n)/2;width=(e-w)*111320*Math.cos(lat0*Math.PI/180)*scale;depth=(n-s)*111320*scale;
  initScene();buildTerrain();buildBoundary();buildWater();
  hydrology=new HydrologyView({world,meta,dem:evolution.base,seeds:volgaMask,barriers:new Uint8Array(responses[7]),surfaceMask,buildings:responses[6],data:hydroData,xy,onBed:setHydraulicBed,onWaveFocus:(p,radius)=>{const center=point(...p);center.y*=state.exag/12;const distance=Math.max(3,radius/1000*6);controls.target.copy(center);camera.position.copy(center).add(state.top?v3(0,distance,.001):v3(distance*.28,distance*.8,distance*.85));controls.update();},onFocus:b=>{const coords=b.geometry.coordinates[0];const lon=coords.reduce((a,p)=>a+p[0],0)/coords.length,lat=coords.reduce((a,p)=>a+p[1],0)/coords.length;const center=point(lon,lat);center.y*=state.exag/12;controls.target.copy(center);camera.position.copy(center).add(state.top?v3(0,1.6,.001):v3(.5,1.3,1.4));controls.update();},onLevel:level=>{for(const mesh of waterGroup.children)if(mesh.userData.volga){mesh.visible=level!==null;if(level!==null)mesh.position.y=(level-hydroData.baseline)*.012;}}});
  wire();setExag(3);select(-1);setMode('hydrology');$('loading').hidden=true;webMCP();
  let last=performance.now();function animate(now){requestAnimationFrame(animate);const dt=Math.max(0,Math.min((now-last)/1000,.05));last=now;
    if(state.playing){time+=dt;if(state.mode==='erosion'&&state.evolving&&!recording){state.year=Math.min(200,state.year+dt*5);$('year').value=state.year;$('yearValue').textContent=Math.round(state.year);if(Math.floor(state.year)!==lastLab){lastLab=Math.floor(state.year);applyEvolution()}if(state.year===200)togglePlay()}}
    hydrology.animate(dt);updateParticles();controls.update();document.querySelector('.compass b').style.transform='rotate('+compassRotation(camera.position.x-controls.target.x,camera.position.z-controls.target.z)+'rad)';hydrology.waterSurface.render(renderer,scene,camera);captureFrame(now);
  }requestAnimationFrame(animate);
}catch(e){$('loading').textContent='Не удалось открыть карту: '+e.message;console.error(e)}}start();
